/bin/zsh -lc "python3 -B - <<'PY'
from pathlib import Path
import json
for p in (Path('AGENTS.md'), Path('.agents/skills/stdo-representation')):
    print(str(p), 'exists=', p.exists(), 'symlink=', p.is_symlink())
    if p.is_symlink(): print('target=', p.readlink())
    if p.name == 'AGENTS.md' and p.is_file(): print(p.read_text())
p=Path('dogfood/t009-frame-projection/run-003/logical-constraint-map.json')
m=json.loads(p.read_text())
print('MAP KEYS', list(m))
for k in ('kind','program_uri','program_sha256','frame_refs','frame_indexes'):
    print(k, json.dumps(m.get(k), indent=2))
for k,v in m.items():
    if k not in ('kind','program_uri','program_sha256','frame_refs','frame_indexes'):
        print(k, type(v).__name__, len(v) if hasattr(v,'__len__') else v)
PY"

